function go(id){if(!MODULES.some(m=>m[0]===id))return;if(!perms().view){toast('Módulo no autorizado');return;}current=id;if(location.hash!=='#'+id)history.pushState(null,'','#'+id);render()}
function enhanceMobileTables(){document.querySelectorAll('#content table').forEach(t=>{const hs=[...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());t.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(td.tagName==='TD'&&hs[i]&&td.colSpan<2)td.dataset.label=hs[i]}))})}
function wireActionButtons(){}
function bindPagers(){document.querySelectorAll('.pager').forEach(pager=>{pager.onclick=e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();e.stopPropagation();action(b.dataset.action,b.dataset.id,b)}})}
function fmtNum(v,decimals=2){const n=Number(v);if(!Number.isFinite(n))return'0';return n.toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:decimals});}
function render(){if(!MODULES.some(x=>x[0]===current))current='dashboard';renderNav();const m=MODULES.find(x=>x[0]===current)||MODULES[0];const titleEl=document.getElementById('title');if(titleEl)titleEl.textContent=m[1];const content=document.getElementById('content');try{const body=(V[current]||generic)(m);content.innerHTML=current==='dashboard'?body:`<section class="module-page" data-module="${esc(current)}">${body}</section>`;if(current==='productos'||current==='sup')renderCatalog();if(current==='recetas'||current==='preelaborados'){const rt=current==='preelaborados'?'prep':'final';renderRecipePager(rt);bindRecipePagerTools(rt)}enhanceMobileTables();wireActionButtons();bindOperationalModuleTools();bindPagers();document.getElementById('sidebar').classList.remove('open')}catch(err){console.error('LRX module render',current,err);content.innerHTML=`<section class="module-page" data-module="${esc(current)}"><div class="card"><h2>Error en ${esc(m[1])}</h2><p>Este módulo encontró un error y fue aislado para no bloquear el resto de LRX.</p><pre style="white-space:pre-wrap;overflow:auto">${esc(err?.stack||err)}</pre><div class="actions"><button class="btn" data-action="go-dashboard">Volver al Dashboard</button></div></div></section>`;const b=content.querySelector('[data-action="go-dashboard"]');if(b)b.onclick=()=>go('dashboard')}}
