function inteligenciaAdministrativa(){
 const invValue=(state.inventory||[]).reduce((n,x)=>n+Number(x.qty||0)*Number(x.unitCost||0),0);
 const low=(state.inventory||[]).filter(x=>Number(x.minQty||0)>0&&Number(x.qty||0)<=Number(x.minQty||0));
 const payables=(state.purchases||[]).filter(x=>['PENDIENTE','PARCIAL'].includes(String(x.status||'').toUpperCase())).reduce((n,x)=>n+Number(x.total||0),0);
 const sales=(state.sales||[]).reduce((n,x)=>n+Number(saleDetail(x).net||0),0);
 const purchases=(state.purchases||[]).reduce((n,x)=>n+Number(x.total||0),0);
 const production=(state.production||[]).length;
 const employeeCount=(state.employees||[]).filter(x=>x.active!==false).length;
 const priceAlerts=(state.purchasePriceHistory||[]).filter(x=>Number(x.increasePct||0)>=Number(state.settings?.priceIncreaseAlertPct||10)).length;
 const permits=(state.permits||[]).filter(x=>x.expiryDate && Math.ceil((new Date(x.expiryDate+'T23:59:59')-Date.now())/86400000)<=30).length;
 const foodCost=sales>0?(purchases/sales*100):0;
 const signals=[];
 if(low.length)signals.push(['warning','Inventario','Hay '+low.length+' insumo(s) en mínimo o por debajo.','inventario']);
 if(payables>0)signals.push(['danger','Cuentas por pagar',money(payables)+' pendientes o parciales.','compras']);
 if(priceAlerts)signals.push(['warning','Precios de compra',priceAlerts+' aumento(s) superan el umbral configurado.','proveedores-comparacion']);
 if(permits)signals.push(['warning','Documentos',permits+' documento(s) vencen o vencieron dentro de 30 días.','documentos-permisos']);
 if(!signals.length)signals.push(['ok','Operación','No hay alertas administrativas críticas con los datos actuales.','reportes']);
 return head('Inteligencia Administrativa','Centro ejecutivo para detectar desviaciones, prioridades y oportunidades de gestión.',`<button class="btn" data-jump="reportes">Ver reportes</button>`)+`
 <section class="intel-grid">
  <article class="card intel-hero"><div class="dash-panel-head"><div><h3>Lectura ejecutiva</h3><p class="muted">Indicadores calculados con la información disponible en LRX.</p></div><span class="status-dot ok">● ACTIVO</span></div><div class="intel-kpis"><div><small>Ventas registradas</small><strong>${money(sales)}</strong></div><div><small>Compras</small><strong>${money(purchases)}</strong></div><div><small>Food Cost observado</small><strong>${foodCost.toFixed(1)}%</strong></div><div><small>Inventario valorizado</small><strong>${money(invValue)}</strong></div></div></article>
  <article class="card"><h3>Prioridades administrativas</h3><div class="intel-signals">${signals.map(x=>`<button class="intel-signal ${x[0]}" data-jump="${x[3]}"><span>${x[0]==='danger'?'!':x[0]==='warning'?'△':'✓'}</span><div><b>${esc(x[1])}</b><small>${esc(x[2])}</small></div><i>›</i></button>`).join('')}</div></article>
  <article class="card"><h3>Capacidad operativa</h3><div class="intel-bars"><div><span>Empleados activos</span><b>${employeeCount}</b></div><div><span>Producciones registradas</span><b>${production}</b></div><div><span>Productos bajo mínimo</span><b>${low.length}</b></div><div><span>Alertas de precio</span><b>${priceAlerts}</b></div></div></article>
  <article class="card"><h3>Acciones rápidas</h3><div class="intel-actions"><button class="btn primary" data-jump="compras">Revisar compras</button><button class="btn" data-jump="foodcost">Analizar Food Cost</button><button class="btn" data-jump="inventario">Revisar inventario</button><button class="btn" data-jump="menu">Menu Engineering</button><button class="btn" data-jump="finanzas">Finanzas</button><button class="btn" data-jump="gerente">Bitácora gerente</button></div></article>
 </section>`;
}
