 const rows=[...map.values()]; const q=String(state._ingredientsQ||'').toLowerCase().trim(); const f=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q));
 return head('Ingredientes','Insumos centralizados reutilizables en recetas, producción y compras.',`<button class="btn primary" data-action="generic-add" data-key="ingredients">＋ Nuevo ingrediente</button> <button class="btn" data-action="ingredients-print">Imprimir / PDF</button> <button class="btn" data-action="generic-export" data-key="ingredients">Excel + CSV</button>`)+
 `<div class="toolbar"><input id="ingredientsQ" class="input search" placeholder="Buscar nombre, categoría o unidad" value="${esc(state._ingredientsQ||'')}"><span class="pill">${f.length} registros</span></div><div class="catalog-results">${f.map(x=>`<article class="catalog-card"><div class="catalog-title"><span class="catalog-id">${esc(x.id||'—')}</span><h3>${esc(x.name||x.detail||'—')}</h3></div><div class="catalog-grid"><div><small>Categoría</small><b>${esc(x.category||'—')}</b></div><div><small>Unidad</small><b>${esc(x.unit||x.standardUnit||'—')}</b></div><div><small>Costo utilizable</small><b>${money(x.cost||x.finalCost||0)}</b></div><div><small>Origen</small><b>${esc(x.status||'—')}</b></div></div><div class="catalog-actions">${x.status==='USUARIO'?`<button class="btn danger" data-action="secure-delete" data-key="ingredients" data-id="${esc(x.id)}">Eliminar</button>`:''}</div></article>`).join('')||'<div class="card empty">No hay ingredientes.</div>'}</div>`;
