 return head('Categorías','Departamentos y categorías centrales para productos, recetas, inventario y reportes.',`<button class="btn primary" data-action="generic-add" data-key="categories">＋ Nueva categoría</button> <button class="btn" data-action="categories-print">Imprimir / PDF</button>`)+
 `<div class="toolbar"><input id="categoriesQ" class="input search" placeholder="Buscar categoría" value="${esc(state._categoriesQ||'')}"><span class="pill">${f.length} categorías</span></div><div class="catalog-results">${f.map((x,i)=>`<article class="catalog-card"><div class="catalog-title"><span class="catalog-id">${String(i+1).padStart(3,'0')}</span><h3>${esc(x)}</h3></div><div class="catalog-grid"><div><small>Productos</small><b>${(master.products||[]).filter(p=>String(p.category||'').trim()===x).length}</b></div><div><small>Estado</small><b>ACTIVA</b></div></div></article>`).join('')||'<div class="card empty">No hay categorías.</div>'}</div>`;
