function generic(m){const key=({proveedores:'suppliers',compras:'purchases','lista-compras':'shopping',inventario:'inventory',movimientos:'movements',merma:'waste',ventas:'sales',promociones:'promotions',eventos:'events',checklists:'records',gerente:'records',reportes:'records',rentabilidad:'sales',foodcost:'records',menu:'sales',finanzas:'dreRecords',ingredientes:'ingredients',categorias:'categories',cocina:'records',bar:'records'})[m[0]]||'records';const rows=Array.isArray(state[key])?state[key]:[];const q=String(state[`_genericQ_${key}`]||'').toLowerCase().trim();const filtered=rows.filter(x=>!q||JSON.stringify(x).toLowerCase().includes(q)).slice().reverse();const size=Math.max(1,Number(state[`_genericSize_${key}`]||25));const pages=Math.max(1,Math.ceil(filtered.length/size));state[`_genericPage_${key}`]=LRXPagination.normalize(state[`_genericPage_${key}`]||0,pages);const page=state[`_genericPage_${key}`],visible=filtered.slice(page*size,(page+1)*size);return head(m[1],m[2],`<button class="btn primary" data-action="generic-add" data-key="${key}">＋ Nuevo registro</button>`)+`<div class="card"><div class="toolbar"><input id="genericQ" data-generic-key="${key}" class="input search" value="${esc(state[`_genericQ_${key}`]||'')}" placeholder="Buscar en ${esc(m[1])}..."><label class="pager-size-label">Por página <select id="genericSize" data-generic-key="${key}">${[25,50,100,250].map(n=>`<option value="${n}" ${size===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn" data-action="generic-export" data-key="${key}">Exportar Excel + CSV</button><button class="btn" data-action="generic-print">Imprimir</button></div><div class="tablewrap"><table><thead><tr><th>Registro</th><th>Fecha</th><th>Detalle</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="genericRows">${visible.map(x=>`<tr><td>${esc(x.id||'—')}</td><td>${fmt(x.date||x.createdAt,true)}</td><td>${esc(x.description||x.name||x.product||x.title||'Registro')}</td><td><span class="status">${esc(x.status||'ACTIVO')}</span></td><td><button class="btn" data-action="generic-edit" data-key="${key}" data-id="${esc(x.id||'')}">Editar</button> <button class="btn danger" data-action="generic-delete" data-key="${key}" data-id="${esc(x.id||'')}">Eliminar</button></td></tr>`).join('')||`<tr><td colspan="5" class="empty">No hay registros.</td></tr>`}</tbody></table></div><div id="genericPager" class="pager">${pagerMarkup('generic-page',page,pages,filtered.length,filtered.length?page*size+1:0,Math.min((page+1)*size,filtered.length),`data-key="${esc(key)}"`)}</div></div>`}

function converter(){return head('Convertidor de Medidas','Conversión entre unidades compatibles.')+`<div class="card formgrid"><div class="field"><label>Cantidad</label><input id="cvq" type="number" value="1"></div><div class="field"><label>De</label><select id="cva"><option>lb</option><option>oz</option><option>g</option><option>kg</option><option>gal</option><option>qt</option><option>pt</option><option>fl oz</option><option>L</option><option>mL</option><option>unidad</option><option>docena</option></select></div><div class="field"><label>A</label><select id="cvb"><option>oz</option><option>lb</option><option>g</option><option>kg</option><option>gal</option><option>qt</option><option>pt</option><option>fl oz</option><option>L</option><option>mL</option><option>unidad</option><option>docena</option></select></div><div class="field"><button class="btn primary" data-action="convert">Convertir</button><strong id="cvres" style="display:block;margin-top:12px"></strong></div></div>`}
function calculator(){return head('Calculadora','Costo, comisión, descuento, utilidad, margen y Food Cost.')+`<div class="card formgrid"><div class="field"><label>Costo</label><input id="cc" type="number" step=".01"></div><div class="field"><label>Precio</label><input id="cp" type="number" step=".01"></div><div class="field"><label>Comisión %</label><input id="cm" type="number" step=".01" value="0"></div><div class="field"><label>Descuento %</label><input id="cd" type="number" step=".01" value="0"></div><div class="full"><button class="btn primary" data-action="calc">Calcular</button><div id="cres" style="margin-top:12px"></div></div></div>`}

function sales(){
 const rows=state.sales||[]; const recipes=allRecipes();
 const details=rows.map(s=>saleDetail(s,recipes));
 const gross=details.reduce((a,r)=>a+r.gross,0),discounts=details.reduce((a,r)=>a+r.discountAmt,0),comm=details.reduce((a,r)=>a+r.commission,0),card=details.reduce((a,r)=>a+r.card,0),net=details.reduce((a,r)=>a+r.net,0),cost=details.reduce((a,r)=>a+r.cost,0),profit=net-cost;
 const channels=state.settings.channels||[];
 return head('POS / Ventas','Registra ventas y calcula automáticamente descuento, comisión, tarjeta, Food Cost y utilidad.',`<button class="btn primary" data-action="new-sale">＋ Registrar venta</button> <button class="btn" data-action="new-channel">＋ Canal</button> <button class="btn" data-action="export-sales">Exportar CSV</button>`)+
 `<div class="grid"><div class="card kpi"><small>Ventas brutas</small><strong>${money(gross)}</strong></div><div class="card kpi"><small>Descuentos</small><strong>${money(discounts)}</strong></div><div class="card kpi"><small>Comisiones</small><strong>${money(comm)}</strong></div><div class="card kpi"><small>Tarjeta</small><strong>${money(card)}</strong></div><div class="card kpi"><small>Venta neta</small><strong>${money(net)}</strong></div><div class="card kpi"><small>Utilidad estimada</small><strong>${money(profit)}</strong></div></div>`+
 `<div class="card" style="margin-top:14px"><h3>Canales de venta</h3><div class="catalog-results">${channels.map(c=>`<article class="catalog-card"><div class="catalog-title"><span class="status">${esc(c.type||'CANAL')}</span><h3>${esc(c.name)}</h3></div><div class="catalog-grid"><div><small>Comisión</small><b>${Number(c.commission||0).toFixed(2)}%</b></div><div><small>Tarjeta</small><b>${Number(c.cardFeePct||0).toFixed(2)}%</b></div><div><small>Cargo fijo</small><b>${money(c.fixedFee)}</b></div><div><small>Estado</small><b>${c.active===false?'INACTIVO':'ACTIVO'}</b></div></div><div class="catalog-actions"><button class="btn" data-action="edit-channel" data-id="${esc(c.name)}">Editar</button><button class="btn danger" data-action="delete-channel" data-id="${esc(c.name)}">Eliminar</button></div></article>`).join('')}</div></div>`+
 `<div class="card" style="margin-top:14px"><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Canal</th><th>Cant.</th><th>Bruto</th><th>Desc.</th><th>Comisión</th><th>Tarjeta</th><th>Neto</th><th>Costo</th><th>Utilidad</th><th>Acciones</th></tr></thead><tbody>${details.slice().reverse().map(r=>`<tr><td>${fmt(r.date,true)}</td><td><b>${esc(r.product)}</b>${r.missing?`<small class="muted">Costo pendiente de receta</small>`:''}</td><td>${esc(r.channel)}</td><td>${esc(r.qty)}</td><td>${money(r.gross)}</td><td>${money(r.discountAmt)}</td><td>${money(r.commission)}</td><td>${money(r.card)}</td><td>${money(r.net)}</td><td>${money(r.cost)}</td><td>${money(r.profit)}</td><td><button class="btn" data-action="edit-sale" data-id="${esc(r.id)}">Editar</button> <button class="btn danger" data-action="delete-sale" data-id="${esc(r.id)}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="12" class="empty">No hay ventas registradas.</td></tr>'}</tbody></table></div></div>`
}

function findProduct(name){const k=String(name||'').trim().toLowerCase();return [...(master.products||[]),...(state.products||[])].find(x=>String(x.name||'').trim().toLowerCase()===k)}
function resolveLinkedProduct(item){
 const pid=String(item?.productId||'').trim();
 if(pid){const byId=[...(master.products||[]),...(state.products||[])].find(x=>String(x.id||'')===pid);if(byId)return byId;}
 const prepId=String(item?.prepId||'').trim();
 if(prepId){const prep=[...(state.preps||[]),...effectiveMaster('preps')].find(x=>String(x.id||'')===prepId);if(prep)return {id:prep.id,name:prep.name,unit:prep.yieldUnit||item.unit||'unit',standardUnit:prep.yieldUnit||item.unit||'unit',cost:Number(prep.cost||0),isPrep:true};}
 const name=String(item?.product||item?.ingredient||'').trim().toLowerCase();
 if(!name)return null;
 return [...(master.products||[]),...(state.products||[])].find(x=>String(x.name||'').trim().toLowerCase()===name)||null;
}
function invRecord(product,unit,cost=0,productId=''){let x=state.inventory.find(i=>{const sameId=productId&&String(i.productId||'')===String(productId);const sameName=String(i.product||'').trim().toLowerCase()===String(product||'').trim().toLowerCase()&&String(i.unit||'').toLowerCase()===String(unit||'').toLowerCase();return sameId||sameName});if(!x){const mp=productId?([...master.products,...(state.products||[])].find(p=>String(p.id||'')===String(productId))):findProduct(product);x={id:'INV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:productId||mp?.id||'P-'+product,product,category:mp?.category||'',unit,qty:0,unitCost:Number(cost||0),minQty:Number(mp?.minQty??mp?.min??0),barcode:mp?.barcode||''};state.inventory.push(x)}else if(productId&&!x.productId)x.productId=productId;return x}
function addInventory(product,qty,unit,cost,ref,type='ENTRADA',productId=''){const q=Number(qty||0),c=Number(cost||0);if(!product||!Number.isFinite(q)||q<=0)return null;const x=invRecord(product,unit,c,productId),beforeQty=Number(x.qty||0),beforeCost=Number(x.unitCost||0),afterQty=beforeQty+q;x.unitCost=afterQty?((beforeQty*beforeCost)+(q*c))/afterQty:c;x.qty=afterQty;state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),date:now(),type,product,qty:q,unit,unitCost:c,total:q*c,ref});return {record:x,beforeQty,beforeCost}}
function subtractInventory(product,qty,unit,ref,type='SALIDA'){const q=Number(qty||0);if(!product||!Number.isFinite(q)||q<=0)return null;const x=invRecord(product,unit,0),before=Number(x.qty||0),after=before-q,negative=after<0;x.qty=after;state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),date:now(),type,product,qty:-q,unit,unitCost:Number(x.unitCost||0),total:-q*Number(x.unitCost||0),ref,negative});return {record:x,beforeQty:before,afterQty:after,negative}}
function consumeRecipe(recipe,scale,ref,type='SALIDA RECETA'){
 const plan=[],missing=[],insufficient=[];
 if(!recipe||!Array.isArray(recipe.items))return {items:[],missing,insufficient,totalCost:0};
 const totals=new Map();
 for(const item of recipe.items){
  const qty=Number(item.qty||0)*Number(scale||1); if(qty<=0)continue;
  let product=resolveLinkedProduct(item);
  if(!product){
   missing.push(item.product||item.ingredient||item.productId||item.prepId||'Ingrediente');
   continue;
  }
  if(!product){missing.push(item.product||item.ingredient||'Ingrediente');continue;}
  const standard=product.standardUnit||product.unit||item.unit||'unit',useUnit=item.unit||standard;
  let converted=qty;
  try{converted=window.LRXCost.convert(qty,useUnit,standard,product.density)}catch(e){missing.push(`${product.name}: unidad ${useUnit}→${standard}`);continue;}
  const key=String(product.id||product.name).toLowerCase();
  const prior=totals.get(key)||{product,qty:0,unit:standard}; prior.qty+=converted; totals.set(key,prior);
 }
 for(const row of totals.values()){
  const inv=invRecord(row.product.name,row.unit,Number(row.product.cost||0)),available=Number(inv.qty||0);
  if(available+1e-9<row.qty)insufficient.push({product:row.product.name,required:row.qty,available,unit:row.unit});
  plan.push(row);
 }
 if(missing.length||insufficient.length)return {items:[],missing:[...new Set(missing)],insufficient,totalCost:0};
 const items=plan.map(row=>{const cost=Number(row.product.cost||invRecord(row.product.name,row.unit,0).unitCost||0)*Number(row.qty||0);return {product:row.product.name,productId:row.product.id,qty:Number(row.qty||0),unit:row.unit,cost,...subtractInventory(row.product.name,Number(row.qty||0),row.unit,ref,type)};});
 return {items,missing:[],insufficient:[],totalCost:items.reduce((a,x)=>a+Number(x.cost||0),0)};
}
function recipeOutputCost(recipe){if(!recipe)return 0;const d=recipeCostDetail(recipe),y=Math.max(1,Number(recipe.yieldQty||1));return d.cost/y}
function reversePurchaseInventory(p){if(!p?.inventoryApplied)return;const inv=state.inventory.find(i=>(String(i.productId||'')===String(p.productId||'')||String(i.product||'').trim().toLowerCase()===String(p.product||'').trim().toLowerCase())&&String(i.unit||'').toLowerCase()===String(p.inventoryUnit||p.unit||'').toLowerCase());const qty=Number(p.inventoryQtyAdded??p.qty??0);if(inv){inv.qty=Math.max(0,Number(inv.qty||0)-qty);if(p.inventoryBeforeUnitCost!=null)inv.unitCost=Number(p.inventoryBeforeUnitCost)}const ref=`COMPRA-${p.id}`;state.movements=state.movements.filter(m=>String(m.ref||'')!==ref);state.movements.push({id:'MOV-REV-'+p.id+'-'+Date.now(),date:now(),type:'REVERSA COMPRA',product:p.product,productId:p.productId||'',qty:-qty,unit:p.inventoryUnit||p.unit,unitCost:Number(p.unitCost||0),total:-qty*Number(p.unitCost||0),ref:`REVERSA-${ref}`,purchaseId:p.purchaseId||p.id});if(inv&&Array.isArray(inv.appliedPurchaseIds))inv.appliedPurchaseIds=inv.appliedPurchaseIds.filter(v=>String(v)!==String(p.id));p.inventoryApplied=false;}

function saleDetail(s,recipes=allRecipes()){
 const items=Array.isArray(s.items)&&s.items.length?s.items:[{product:s.product||'',qty:Number(s.qty||1),price:Number(s.price||0)}];
 const gross=items.reduce((a,x)=>a+Number(x.price||0)*Number(x.qty||1),0),discountAmt=gross*Number(s.discount||0)/100,afterDiscount=gross-discountAmt;
 const channel=(state.settings.channels||[]).find(c=>String(c.name||'').trim().toLowerCase()===String(s.channel||'').trim().toLowerCase());
 const commissionPct=Number(s.commission??channel?.commission??0),commission=afterDiscount*commissionPct/100;
 const configuredCardPct=Number(channel?.cardFeePct||0),configuredFixedFee=Number(channel?.fixedFee||0);
 const card=Number.isFinite(Number(s.cardFee))&&Number(s.cardFee)>0?Number(s.cardFee):afterDiscount*configuredCardPct/100;
 const fixedFee=Number(s.fixedFee??configuredFixedFee??0),net=afterDiscount-commission-card-fixedFee;
 let cost=Number(s.cost||0),missing=[];
 if(!cost){for(const item of items){const rec=recipes.find(x=>String(x.id)===String(item.recipeId||'')||String(x.name||'').trim().toLowerCase()===String(item.product||'').trim().toLowerCase());if(rec){const d=recipeCostDetail(rec);cost+=d.cost/Math.max(1,Number(rec.yieldQty||1))*Number(item.qty||1);missing.push(...(d.missing||[]))}else missing.push(item.product||'Receta no encontrada')}}
 return {...s,commissionPct,commission,card,fixedFee,net,cost,profit:net-cost,missing:[...new Set(missing)].length>0};
}
function channelModal(name=''){const channels=state.settings.channels||[];const r=name?channels.find(x=>String(x.name)===String(name)):null;modal(`<h3>${r?'Editar':'Nuevo'} canal de venta</h3><div class="formgrid"><div class="field"><label>Nombre</label><input id="chName" value="${esc(r?.name||'')}"></div><div class="field"><label>Tipo</label><input id="chType" value="${esc(r?.type||'Directo')}" placeholder="Delivery, Directo, Catering..."></div><div class="field"><label>Comisión %</label><input id="chCom" type="number" min="0" step=".1" value="${Number(r?.commission||0)}"></div><div class="field"><label>Tarjeta %</label><input id="chCard" type="number" min="0" step=".01" value="${Number(r?.cardFeePct||0)}"></div><div class="field"><label>Cargo fijo por orden</label><input id="chFixed" type="number" min="0" step=".01" value="${Number(r?.fixedFee||0)}"></div><div class="field"><label><input id="chActive" type="checkbox" ${r?.active!==false?'checked':''}> Activo</label></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-channel" data-id="${esc(name)}">Guardar</button></div>`)}
function saveChannel(oldName=''){const name=document.getElementById('chName').value.trim();if(!name)return toast('Indica el nombre del canal');const channels=state.settings.channels||[];if(!oldName&&channels.some(x=>String(x.name).toLowerCase()===name.toLowerCase()))return toast('Ese canal ya existe');const obj={name,type:document.getElementById('chType').value.trim()||'Directo',commission:Math.max(0,Number(document.getElementById('chCom').value||0)),cardFeePct:Math.max(0,Number(document.getElementById('chCard').value||0)),fixedFee:Math.max(0,Number(document.getElementById('chFixed').value||0)),active:document.getElementById('chActive').checked};const i=channels.findIndex(x=>String(x.name)===String(oldName));if(i>=0){const prev=channels[i].name;channels[i]=obj;state.sales.forEach(s=>{if(s.channel===prev)s.channel=name;s.commission=s.channel===name?obj.commission:s.commission});}else channels.push(obj);state.settings.channels=channels;save();close();render();toast('Canal guardado')}
function deleteChannel(name){if(!confirm('¿Eliminar este canal? Las ventas históricas conservarán su nombre.'))return;state.settings.channels=(state.settings.channels||[]).filter(x=>String(x.name)!==String(name));save();render()}
function reverseSaleInventory(s){const impact=Array.isArray(s.inventoryImpact)?s.inventoryImpact:[];impact.forEach(x=>{if(!Number(x.qty||0))return;const q=Number(x.qty||0),unit=x.unit||'unit',pid=x.productId||'';let inv=(state.inventory||[]).find(i=>pid&&String(i.productId||i.id)===String(pid));if(!inv&&x.product)inv=(state.inventory||[]).find(i=>String(i.product||'').trim().toLowerCase()===String(x.product).trim().toLowerCase()&&String(i.unit||'').trim().toLowerCase()===String(unit).trim().toLowerCase());if(inv){inv.qty=Number(inv.qty||0)+q;state.movements.push({id:'MOV-'+Date.now()+'-'+Math.random().toString(36).slice(2,5),date:now(),type:'REVERSA VENTA',product:inv.product,productId:inv.productId||inv.id,qty:q,unit,unitCost:Number(x.unitCost||inv.unitCost||0),total:q*Number(x.unitCost||inv.unitCost||0),ref:s.id});}});s.inventoryDeducted=false;s.inventoryImpact=[];}
function saleItemRow(item={},i=0){const recipes=allRecipes();return `<div class="sale-item-row" data-sale-item="${i}"><select class="sale-item-product input"><option value="">Seleccionar plato…</option>${recipes.map(r=>`<option value="${esc(r.name)}" ${String(r.name)===String(item.product||'')?'selected':''}>${esc(r.name)}</option>`).join('')}</select><input class="sale-item-qty input" type="number" min="1" step="1" value="${Number(item.qty||1)}"><input class="sale-item-price input" type="number" min="0" step=".01" value="${Number(item.price||0)}"><button type="button" class="btn danger sale-item-remove" title="Quitar">×</button></div>`}
function saleModal(existing=null){
 const channels=state.settings.channels||[]; const opts=channels.filter(c=>c.active!==false).map(c=>`<option value="${esc(c.name)}" data-commission="${Number(c.commission||0)}" data-cardpct="${Number(c.cardFeePct||0)}" ${existing?.channel===c.name?'selected':''}>${esc(c.name)} · ${Number(c.commission||0)}%</option>`).join('');
 const items=Array.isArray(existing?.items)&&existing.items.length?existing.items:[{product:existing?.product||'',qty:existing?.qty||1,price:existing?.price||0}];
 modal(`<h3>${existing?'Editar':'Registrar'} venta</h3><div class="field full"><label>Artículos de la orden (hasta 10)</label><div id="saleItems" class="sale-items">${items.slice(0,10).map((x,i)=>saleItemRow(x,i)).join('')}</div><button type="button" class="btn" id="addSaleItem">＋ Agregar artículo</button></div><div class="formgrid"><div class="field"><label>Canal</label><select id="saleChannel">${opts}</select></div><div class="field"><label>Comisión %</label><input id="saleCommission" type="number" min="0" max="100" step=".1" value="${Number(existing?.commission||0)}"></div><div class="field"><label>Descuento %</label><input id="saleDiscount" type="number" min="0" max="100" step=".1" value="${Number(existing?.discount||0)}"></div><div class="field"><label>Procesamiento tarjeta $</label><input id="saleCard" type="number" min="0" step=".01" value="${Number(existing?.cardFee||0)}"></div><div class="field"><label>Motivo descuento</label><input id="saleDiscountReason" value="${esc(existing?.discountReason||'')}" placeholder="Happy Hour, cupón, empleado..."></div><div class="field"><label>Fecha</label><input id="saleDate" type="date" value="${esc(String(existing?.date||new Date().toISOString().slice(0,10)).slice(0,10))}"></div><div class="field full"><div id="salePreview" class="resultbox">Agrega uno o varios artículos para calcular la orden.</div></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-sale" data-id="${esc(existing?.id||'')}">Guardar venta</button></div>`);
 const box=document.getElementById('saleItems');
 const bindRows=()=>{box.querySelectorAll('.sale-item-product').forEach(el=>el.onchange=()=>{const row=el.closest('.sale-item-row'),r=allRecipes().find(x=>String(x.name)===el.value),price=row.querySelector('.sale-item-price');if(r&&price&&!Number(price.value))price.value=Number(r.salePrice||r.price||0);previewSale()});box.querySelectorAll('.sale-item-qty,.sale-item-price').forEach(el=>el.oninput=previewSale);box.querySelectorAll('.sale-item-remove').forEach(btn=>btn.onclick=()=>{if(box.children.length>1){btn.closest('.sale-item-row').remove();previewSale()}})};
 document.getElementById('addSaleItem').onclick=()=>{if(box.children.length>=10)return toast('Máximo 10 artículos por venta');box.insertAdjacentHTML('beforeend',saleItemRow({},box.children.length));bindRows();};
 document.getElementById('saleChannel').onchange=()=>{const opt=document.getElementById('saleChannel').selectedOptions[0];if(!existing)document.getElementById('saleCommission').value=Number(opt?.dataset.commission||0);previewSale()};['saleCommission','saleDiscount','saleCard'].forEach(id=>document.getElementById(id).oninput=previewSale);bindRows();previewSale();
}
function readSaleItems(){return [...document.querySelectorAll('#saleItems .sale-item-row')].map(row=>({product:row.querySelector('.sale-item-product')?.value.trim(),qty:Number(row.querySelector('.sale-item-qty')?.value||0),price:Number(row.querySelector('.sale-item-price')?.value||0)})).filter(x=>x.product&&x.qty>0&&x.price>=0)}
function previewSale(){const box=document.getElementById('salePreview');if(!box)return;const items=readSaleItems(),d=Number(document.getElementById('saleDiscount')?.value||0),c=Number(document.getElementById('saleCommission')?.value||0),card=Number(document.getElementById('saleCard')?.value||0);let gross=0,cost=0;for(const x of items){const r=allRecipes().find(y=>String(y.name||'').trim().toLowerCase()===x.product.toLowerCase());gross+=x.price*x.qty;cost+=r?recipeCostDetail(r).cost/Math.max(1,Number(r.yieldQty||1))*x.qty:0}const disc=gross*d/100,net=gross-disc-(gross-disc)*c/100-card;box.innerHTML=`${items.length} artículo(s) · Bruto <b>${money(gross)}</b> · Descuento <b>${money(disc)}</b> · Neto <b>${money(net)}</b> · Costo <b>${money(cost)}</b> · Utilidad <b>${money(net-cost)}</b>`}
