function purchaseCatalogProducts(){
 const rows=[...(master.products||[]),...(state.products||[])];
 const seen=new Set();
 return rows.filter(p=>{const k=String(p?.id||p?.code||p?.sku||p?.name||'').trim().toLowerCase();if(!k||seen.has(k))return false;seen.add(k);return true});
}
function purchaseLineMatch(line){
 const normalizeCode=v=>String(v??'').replace(/[^A-Za-z0-9]/g,'').toLowerCase();
 const normName=v=>String(v??'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
 const code=normalizeCode(line?.code);
 const name=normName(line?.product);
 const catalog=purchaseCatalogProducts();
 if(code){
   const hit=catalog.find(p=>[p?.code,p?.sku,p?.itemCode,p?.item_code,p?.upc,p?.barcode,p?.id].some(v=>normalizeCode(v)===code));
   if(hit)return {product:hit,reason:'Código'};
 }
 if(name){
   const hit=catalog.find(p=>normName(p?.name)===name);
   if(hit)return {product:hit,reason:'Nombre exacto'};
 }
 return null;
}
function purchaseLineRow(x={},i=0){
 const match=purchaseLineMatch(x), exists=!!match;
 const action=exists
   ? `<button type="button" class="btn purchase-create-btn is-existing" disabled title="El producto ya existe en el catálogo">✓ Existe</button>`
   : `<button type="button" class="btn purchase-create-btn" data-action="purchase-create-product" data-line="${i}" title="Crear este producto en el catálogo">＋ Crear</button>`;
 const cols='minmax(180px,2fr) 90px 105px 115px minmax(78px,auto) 42px';
 return `<div class="purchase-line" data-i="${i}" data-code="${esc(x.code||'')}" data-product-id="${esc(x.productId||'')}" style="display:grid;grid-template-columns:${cols};gap:8px;align-items:end;padding:10px 0;border-bottom:1px solid var(--line)">
 <div class="field"><label>Producto</label><input class="bp-line-product input" list="buyProducts" value="${esc(x.product||'')}" placeholder="Producto / ingrediente"></div>
 <div class="field"><label>Cantidad</label><input class="bp-line-qty input" type="number" min="0.001" step=".001" value="${esc(x.qty??'')}"></div>
 <div class="field"><label>Unidad</label><input class="bp-line-unit input" value="${esc(x.unit||'lb')}"></div>
 <div class="field"><label>Costo unit.</label><input class="bp-line-cost input" type="number" min="0" step=".0001" value="${Number(x.unitCost||0)||''}"></div>
 <div class="field"><label>Producto</label>${action}</div>
 <button type="button" class="btn danger bp-line-remove" title="Eliminar línea">×</button></div>`;
}
function updatePurchaseLineCreateState(row){
 if(!row)return;
 const productInput=row.querySelector('.bp-line-product');
 const code=String(row.dataset.code||'').trim();
 const match=purchaseLineMatch({product:productInput?.value||'',code});
 const host=row.querySelector('.purchase-create-btn')?.parentElement;
 if(!host)return;
 host.innerHTML=match
   ? `<label>Producto</label><button type="button" class="btn purchase-create-btn is-existing" disabled title="El producto ya existe en el catálogo">✓ Existe</button>`
   : `<label>Producto</label><button type="button" class="btn purchase-create-btn" data-action="purchase-create-product" data-line="${row.dataset.i}" title="Crear este producto en el catálogo">＋ Crear</button>`;
}
function updatePurchasePreview(){
 const box=document.getElementById('buyPreview');
 const rows=[...document.querySelectorAll('.purchase-line')];
 const total=rows.reduce((sum,row)=>{
   const qty=Number(row.querySelector('.bp-line-qty')?.value||0);
   const cost=Number(row.querySelector('.bp-line-cost')?.value||0);
   return sum+(qty>0&&cost>=0?qty*cost:0);
 },0);
 if(box)box.innerHTML=`Total estimado: <b>${money(total)}</b>`;
 return total;
}
function bindPurchaseLines(products=[]){
 document.querySelectorAll('.purchase-line').forEach(row=>{
  const prod=row.querySelector('.bp-line-product'),qty=row.querySelector('.bp-line-qty'),unit=row.querySelector('.bp-line-unit'),cost=row.querySelector('.bp-line-cost');
  const sync=()=>{const n=String(prod?.value||'').trim().toLowerCase();const p=products.find(x=>String(x.name||'').trim().toLowerCase()===n);if(p){row.dataset.productId=p.id||'';if(!unit.value)unit.value=p.purchaseUnit||p.standardUnit||p.unit||'lb';if(!Number(cost.value))cost.value=Number(p.packPrice||p.cost||p.finalCost||0)}else if(n)delete row.dataset.productId;updatePurchaseLineCreateState(row);};
  prod?.addEventListener('change',()=>{sync();updatePurchasePreview();persistPurchaseDraft()});prod?.addEventListener('input',()=>{if(prod.value.length>2)sync();updatePurchasePreview();persistPurchaseDraft()});qty?.addEventListener('input',()=>{updatePurchasePreview();persistPurchaseDraft()});unit?.addEventListener('input',()=>{updatePurchasePreview();persistPurchaseDraft()});cost?.addEventListener('input',()=>{updatePurchasePreview();persistPurchaseDraft()});
  row.querySelector('.bp-line-remove')?.addEventListener('click',()=>{const rows=document.querySelectorAll('.purchase-line');if(rows.length>1){row.remove();updatePurchasePreview();persistPurchaseDraft()}});
  sync();
 });
}
