 capturePurchaseDraft();
 window._lrxPurchaseCreateContext={lineIndex:String(lineIndex),startedAt:window._lrxPurchaseDraft?.startedAt||now()};
 const name=row.querySelector('.bp-line-product')?.value.trim()||'';
