function formatModal(returnProductionId=''){modal(`<h3>Crear tamaño de etiqueta</h3><p class="muted">Define el tamaño físico que aparecerá en el selector de etiquetas.</p><div class="formgrid"><div class="field"><label>Nombre</label><input id="fn" placeholder="Ej. 2 × 1.5 in"></div><div class="field"><label>Ancho (in)</label><input id="fw" type="number" min="0.1" step=".01" placeholder="4"></div><div class="field"><label>Alto (in)</label><input id="fh" type="number" min="0.1" step=".01" placeholder="3"></div></div><div class="actions" style="margin-top:12px"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-format">Guardar tamaño</button></div>`);document.querySelector('[data-action="save-format"]').onclick=()=>{const w=+document.getElementById('fw').value,h=+document.getElementById('fh').value;if(!(w>0&&h>0))return toast('Indica ancho y alto válidos');const name=document.getElementById('fn').value.trim()||`${w} × ${h} in`;state.settings.labelFormats=Array.isArray(state.settings.labelFormats)?state.settings.labelFormats:[];state.settings.labelFormats.push({name,w,h});save();close();const prod=returnProductionId?state.production.find(x=>String(x.id)===String(returnProductionId)):null;if(prod)return labelModal(prod);render();toast(`Tamaño ${name} creado`)}}
function convert(){const q=+document.getElementById('cvq').value,a=document.getElementById('cva').value,b=document.getElementById('cvb').value,m={g:1,oz:28.349523125,lb:453.59237,kg:1000},v={mL:1,'fl oz':29.5735295625,pt:473.176473,qt:946.352946,gal:3785.411784,L:1000},c={unidad:1,docena:12};let r=null;if(m[a]&&m[b])r=q*m[a]/m[b];else if(v[a]&&v[b])r=q*v[a]/v[b];else if(c[a]&&c[b])r=q*c[a]/c[b];document.getElementById('cvres').textContent=r==null?'Conversión no permitida sin factor de densidad.':`${q} ${a} = ${r.toLocaleString(undefined,{maximumFractionDigits:6})} ${b}`}
function calc(){const c=+document.getElementById('cc').value||0,p=+document.getElementById('cp').value||0,cm=(+document.getElementById('cm').value||0)/100,cd=(+document.getElementById('cd').value||0)/100,n=p*(1-cd)*(1-cm),u=n-c,mar=n?u/n*100:0,fc=n?c/n*100:0;document.getElementById('cres').innerHTML=`<div class="grid"><div class="card"><small>Venta neta</small><strong>${money(n)}</strong></div><div class="card"><small>Utilidad</small><strong>${money(u)}</strong></div><div class="card"><small>Margen</small><strong>${mar.toFixed(2)}%</strong></div><div class="card"><small>Food Cost</small><strong>${fc.toFixed(2)}%</strong></div></div>`}

function yieldAnalysisBody(){
 const studies=Array.isArray(state.yieldStudies)?state.yieldStudies.slice().reverse():[], products=[...new Map([...inventoryMasterRows().map(x=>({id:x.productId||x.id,name:x.product||''})),...(master.products||[]).map(x=>({id:x.id,name:x.name}))].filter(x=>x.name).map(x=>[String(x.id||x.name),x])).values()].sort((a,b)=>String(a.name).localeCompare(String(b.name))), productFilter=String(state._yieldProductFilter||''), supplierFilter=String(state._yieldSupplierFilter||'').toLowerCase(), filtered=studies.filter(x=>(!productFilter||String(x.product||'').toLowerCase()===productFilter.toLowerCase())&&(!supplierFilter||String(x.supplier||'').toLowerCase().includes(supplierFilter))), totalGross=studies.reduce((n,x)=>n+Number(x.gross||0),0), totalClean=studies.reduce((n,x)=>n+Number(x.clean||0),0), totalWaste=studies.reduce((n,x)=>n+Number(x.waste||0),0), avgYield=totalGross?totalClean/totalGross*100:0, productOptions=products.map(x=>`<option value="${esc(x.name)}" ${String(x.name).toLowerCase()===productFilter.toLowerCase()?'selected':''}>${esc(x.name)}</option>`).join('');
 const map={};studies.forEach(x=>{const k=String(x.product||'').toLowerCase()+'|'+String(x.supplier||'').toLowerCase();if(!map[k])map[k]={product:x.product,supplier:x.supplier,tests:0,waste:0,gross:0,clean:0,cost:0,real:0};const r=map[k];r.tests++;r.waste+=Number(x.wastePct||0);r.gross+=Number(x.gross||0);r.clean+=Number(x.clean||0);r.cost+=Number(x.purchaseCost||0);r.real+=Number(x.cleanCost||0)});const compares=Object.values(map).map(r=>({...r,yield:r.gross?r.clean/r.gross*100:0,avgWaste:r.tests?r.waste/r.tests:0,avgCost:r.tests?r.cost/r.tests:0,realCost:r.tests?r.real/r.tests:0})).sort((a,b)=>a.realCost-b.realCost);
 return `<div class="yield-kpis"><div class="card kpi"><small>Estudios</small><strong>${studies.length}</strong><span>Pruebas registradas</span></div><div class="card kpi"><small>Merma total</small><strong>${fmtNum(totalWaste)}</strong><span>Unidad según estudio</span></div><div class="card kpi"><small>Rendimiento promedio</small><strong>${avgYield.toFixed(1)}%</strong><span>Peso limpio / bruto</span></div><div class="card kpi"><small>Productos evaluados</small><strong>${new Set(studies.map(x=>String(x.product||'').toLowerCase())).size}</strong><span>Comparación real</span></div></div><section class="card yield-card"><div class="yield-section-title"><h3>Nuevo estudio de rendimiento</h3><p>Registra peso bruto, peso limpio y costo para obtener automáticamente merma, rendimiento y costo real limpio.</p></div><div class="yield-grid"><label>Producto<select id="yrProduct"><option value="">Selecciona producto</option>${productOptions}</select></label><label>Proveedor<input id="yrSupplier" placeholder="Proveedor"></label><label>Fecha<input id="yrDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Peso bruto<input id="yrGross" type="number" min="0.001" step="0.001" placeholder="10"></label><label>Peso limpio<input id="yrClean" type="number" min="0" step="0.001" placeholder="8.2"></label><label>Unidad<select id="yrUnit"><option>lb</option><option>oz</option><option>kg</option><option>unidad</option></select></label><label>Costo de compra / unidad<input id="yrCost" type="number" min="0" step="0.0001" placeholder="2.28"></label><label>Responsable<input id="yrUser" value="${esc(currentUser().name||'')}" placeholder="Nombre"></label><label class="yield-full">Observaciones<input id="yrNote" placeholder="Piel, grasa, hueso, recortes..."></label></div><div id="yieldResult" class="yield-result">Ingresa peso bruto y peso limpio para calcular.</div><div class="toolbar"><button class="btn primary" data-action="yield-save">💾 Guardar estudio</button><button class="btn" data-action="yield-clear">↻ Limpiar</button><button class="btn" data-action="yield-export">⬇️ Exportar CSV</button></div></section><section class="card yield-card"><div class="yield-section-title"><h3>Comparación de proveedores</h3><p>Compara el costo real utilizable después de la merma.</p></div><div class="toolbar"><select id="yrFilterProduct" class="input"><option value="">Todos los productos</option>${productOptions}</select><input id="yrFilterSupplier" class="input" placeholder="Filtrar proveedor" value="${esc(state._yieldSupplierFilter||'')}"></div><div class="tablewrap"><table class="yield-table"><thead><tr><th>Producto</th><th>Proveedor</th><th>Pruebas</th><th>Merma</th><th>Rend.</th><th>Costo compra</th><th>Costo real limpio</th><th>Posición</th></tr></thead><tbody>${compares.filter(r=>!productFilter||String(r.product).toLowerCase()===productFilter.toLowerCase()).map((r,i)=>`<tr><td><b>${esc(r.product)}</b></td><td>${esc(r.supplier||'—')}</td><td>${r.tests}</td><td>${r.avgWaste.toFixed(1)}%</td><td>${r.yield.toFixed(1)}%</td><td>${money(r.avgCost)}</td><td>${money(r.realCost)}</td><td><span class="status">${i+1}</span></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No hay estudios suficientes para comparar.</td></tr>'}</tbody></table></div></section><section class="card yield-card"><div class="yield-section-title"><h3>Historial de estudios</h3><p>Todos los estudios quedan almacenados para auditoría y comparación.</p></div><div class="tablewrap"><table class="yield-table"><thead><tr><th>Fecha</th><th>Producto</th><th>Proveedor</th><th>Bruto</th><th>Limpio</th><th>Merma</th><th>% Merma</th><th>Costo real</th><th>Responsable</th><th></th></tr></thead><tbody>${filtered.map(x=>`<tr><td>${fmt(x.date)}</td><td>${esc(x.product)}</td><td>${esc(x.supplier||'—')}</td><td>${fmtNum(x.gross)} ${esc(x.unit)}</td><td>${fmtNum(x.clean)} ${esc(x.unit)}</td><td>${fmtNum(x.waste)} ${esc(x.unit)}</td><td>${Number(x.wastePct||0).toFixed(2)}%</td><td>${money(x.cleanCost)}</td><td>${esc(x.user||'—')}</td><td><button class="btn danger" data-action="yield-delete" data-id="${esc(x.id)}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="10" class="empty">No hay estudios registrados.</td></tr>'}</tbody></table></div></section>`;
}
function yieldAnalysisModule(){return head('Rendimiento, Merma y Compra','Calcula pérdida real, rendimiento y costo utilizable después de la merma.',`<button class="btn" data-action="yield-export">Exportar CSV</button> <button class="btn" data-action="generic-print">Imprimir / PDF</button>`)+yieldAnalysisBody()}
function calculateYieldPreview(){const gross=Number(document.getElementById('yrGross')?.value||0),clean=Number(document.getElementById('yrClean')?.value||0),cost=Number(document.getElementById('yrCost')?.value||0),out=document.getElementById('yieldResult');if(!out)return;const unit=document.getElementById('yrUnit')?.value||'lb',waste=Math.max(0,gross-clean),wastePct=gross?waste/gross*100:0,yieldPct=gross?clean/gross*100:0,cleanCost=clean>0?cost*gross/clean:0;out.innerHTML=gross>0&&clean>=0&&clean<=gross?`<b>Merma:</b> ${fmtNum(waste)} ${esc(unit)} · <b>Pérdida:</b> ${wastePct.toFixed(2)}% · <b>Rendimiento:</b> ${yieldPct.toFixed(2)}% · <b>Costo real limpio:</b> ${money(cleanCost)}`:'Ingresa peso bruto y peso limpio para calcular.'}
function saveYieldStudy(){const product=document.getElementById('yrProduct')?.value.trim(),supplier=document.getElementById('yrSupplier')?.value.trim()||'',date=document.getElementById('yrDate')?.value||new Date().toISOString().slice(0,10),gross=Number(document.getElementById('yrGross')?.value||0),clean=Number(document.getElementById('yrClean')?.value||0),unit=document.getElementById('yrUnit')?.value||'lb',purchaseCost=Number(document.getElementById('yrCost')?.value||0),user=document.getElementById('yrUser')?.value.trim()||currentUser().name||'',note=document.getElementById('yrNote')?.value.trim()||'';if(!product||gross<=0||clean<0||clean>gross)return toast('Completa producto y pesos válidos');const waste=gross-clean,wastePct=gross?waste/gross*100:0,cleanCost=clean>0?purchaseCost*gross/clean:0;state.yieldStudies=Array.isArray(state.yieldStudies)?state.yieldStudies:[];state.yieldStudies.unshift({id:'YLD-'+Date.now(),date,product,productId:inventoryMasterRows().find(x=>String(x.product).toLowerCase()===product.toLowerCase())?.productId||'',supplier,gross,clean,waste,wastePct,yieldPct:gross?clean/gross*100:0,unit,purchaseCost,cleanCost,user,note,createdAt:now()});save();render();toast('Estudio de rendimiento guardado')}
function deleteYieldStudy(id){state.yieldStudies=(state.yieldStudies||[]).filter(x=>String(x.id)!==String(id));save();render();toast('Estudio eliminado')}
function exportYieldStudies(){const rows=(state.yieldStudies||[]).map(x=>({...x}));if(!rows.length)return toast('No hay estudios para exportar');exportRows(rows,'LRX_Rendimiento_Merma_Compra');exportExcel(rows,'LRX_Rendimiento_Merma_Compra')}
function wasteModule(){
 const rows=(state.movements||[]).filter(x=>String(x.type||'').toUpperCase().includes('MERMA')).slice().reverse(),total=rows.reduce((n,x)=>n+Math.abs(Number(x.qty||0))*Number(x.unitCost||0),0);
 return head('Merma','Registro de desperdicios, causa, responsable y costo.',`<button class="btn primary" data-action="new-waste">＋ Registrar merma</button> <button class="btn" data-action="generic-export" data-key="movements">Exportar</button> <button class="btn" data-action="generic-print">Imprimir / PDF</button>`)+`<div class="grid"><div class="card kpi"><small>Registros</small><strong>${rows.length}</strong></div><div class="card kpi"><small>Costo de merma</small><strong>${money(total)}</strong></div></div><div class="card yield-shortcut"><b>📉 Rendimiento, Merma y Compra</b><p class="muted">Calculadora integrada: bruto, limpio, % pérdida, rendimiento, costo real y comparación por proveedor.</p></div>`+yieldAnalysisBody()+`<div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Cantidad</th><th>Costo</th><th>Causa</th><th>Responsable</th><th>Referencia</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${fmt(x.date,true)}</td><td>${esc(x.product||'—')}</td><td>${esc(Math.abs(Number(x.qty||0)))} ${esc(x.unit||'')}</td><td>${money(Math.abs(Number(x.qty||0))*Number(x.unitCost||0))}</td><td>${esc(x.reason||'—')}</td><td>${esc(x.employee||'—')}</td><td>${esc(x.ref||'—')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No hay mermas registradas.</td></tr>'}</tbody></table></div>`;
}
function wasteModal(){
 const products=inventoryMasterRows();
 modal(`<h3>Registrar merma</h3><div class="formgrid"><div class="field full"><label>Producto</label><input id="wmProduct" list="wmProducts"><datalist id="wmProducts">${products.map(x=>`<option value="${esc(x.product)}">`).join('')}</datalist></div><div class="field"><label>Cantidad</label><input id="wmQty" type="number" min="0.001" step="0.001"></div><div class="field"><label>Unidad</label><input id="wmUnit" value="unidad"></div><div class="field"><label>Costo unitario</label><input id="wmCost" type="number" step="0.000001" value="0"></div><div class="field"><label>Causa</label><select id="wmReason"><option>Vencimiento</option><option>Preparación</option><option>Daño</option><option>Sobreproducción</option><option>Contaminación</option><option>Error de porción</option><option>Otro</option></select></div><div class="field"><label>Responsable</label><input id="wmEmployee"></div><div class="field full"><label>Nota</label><textarea id="wmNote" rows="2"></textarea></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-waste">Guardar merma</button></div>`);
 document.getElementById('wmProduct')?.addEventListener('change',()=>{const p=inventoryMasterRows().find(x=>String(x.product||'').toLowerCase()===String(document.getElementById('wmProduct').value||'').toLowerCase());if(p){document.getElementById('wmUnit').value=p.unit||'unidad';document.getElementById('wmCost').value=Number(p.unitCost||0)}});
}
function saveWaste(){
 const product=document.getElementById('wmProduct')?.value.trim(),qty=Number(document.getElementById('wmQty')?.value||0),unit=document.getElementById('wmUnit')?.value.trim()||'unidad',cost=Number(document.getElementById('wmCost')?.value||0),reason=document.getElementById('wmReason')?.value||'Otro',employee=document.getElementById('wmEmployee')?.value.trim()||'',note=document.getElementById('wmNote')?.value.trim()||'';
 if(!product||qty<=0)return toast('Completa producto y cantidad');
 let inv=inventoryMasterRows().find(x=>String(x.product||'').toLowerCase()===product.toLowerCase()&&String(x.unit||'').toLowerCase()===unit.toLowerCase());
 if(!inv)return toast('Producto/unidad no encontrado en inventario');
 const target=state.inventory.find(x=>String(x.id)===String(inv.id))||inv;const before=Number(target.qty||0);if(qty>before)return toast(`No hay existencia suficiente. Disponible: ${before} ${unit}`);
 target.qty=before-qty;target.unitCost=cost||Number(target.unitCost||0);
 state.movements.push({id:'MOV-'+Date.now(),date:now(),type:'MERMA',product,productId:target.productId||'',qty:-qty,unit,unitCost:target.unitCost,total:-qty*target.unitCost,reason,employee,note,ref:'MERMA-'+Date.now()});
 state.waste=Array.isArray(state.waste)?state.waste:[];state.waste.push({id:'WST-'+Date.now(),date:now(),product,productId:target.productId||'',qty,unit,unitCost:target.unitCost,cost:qty*target.unitCost,reason,employee,note});save();close();render();toast('Merma registrada e inventario descontado');
}
function transferModal(){
 const locations=Array.from(new Set((state.inventory||[]).map(x=>x.location).filter(Boolean))).concat(['Cocina','Bar','Almacén']).filter((x,i,a)=>a.indexOf(x)===i);
 modal(`<h3>Transferencia entre ubicaciones</h3><div class="formgrid"><div class="field full"><label>Producto</label><input id="trProduct" list="trProducts"><datalist id="trProducts">${inventoryMasterRows().map(x=>`<option value="${esc(x.product)}">`).join('')}</datalist></div><div class="field"><label>Cantidad</label><input id="trQty" type="number" min="0.001" step="0.001"></div><div class="field"><label>Unidad</label><input id="trUnit" value="unidad"></div><div class="field"><label>Desde</label><select id="trFrom">${locations.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Hacia</label><select id="trTo">${locations.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><div class="actions"><button class="btn" data-action="close">Cancelar</button><button class="btn primary" data-action="save-transfer">Transferir</button></div>`);
}
function saveTransfer(){
 const product=document.getElementById('trProduct')?.value.trim(),qty=Number(document.getElementById('trQty')?.value||0),unit=document.getElementById('trUnit')?.value.trim()||'unidad',from=document.getElementById('trFrom')?.value||'Almacén',to=document.getElementById('trTo')?.value||'Cocina';if(!product||qty<=0)return toast('Completa producto y cantidad');if(from===to)return toast('Las ubicaciones deben ser diferentes');
 const base=inventoryMasterRows().find(x=>String(x.product||'').toLowerCase()===product.toLowerCase());if(!base)return toast('Producto no encontrado');let src=state.inventory.find(x=>String(x.product||'').toLowerCase()===product.toLowerCase()&&String(x.unit||'').toLowerCase()===unit.toLowerCase()&&String(x.location||'Almacén')===from);if(!src||Number(src.qty||0)<qty)return toast('Existencia insuficiente en la ubicación origen');src.qty=Number(src.qty||0)-qty;let dst=state.inventory.find(x=>String(x.product||'').toLowerCase()===product.toLowerCase()&&String(x.unit||'').toLowerCase()===unit.toLowerCase()&&String(x.location||'Almacén')===to);if(!dst){dst={id:'INV-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),productId:src.productId||base.productId||'',product,unit,location:to,qty:0,unitCost:Number(src.unitCost||base.unitCost||0),minQty:Number(src.minQty||0),maxQty:Number(src.maxQty||0)};state.inventory.push(dst)}dst.qty=Number(dst.qty||0)+qty;state.movements.push({id:'MOV-'+Date.now(),date:now(),type:'TRANSFERENCIA',product,productId:src.productId||'',qty,unit,unitCost:Number(src.unitCost||0),from,to,ref:'TRF-'+Date.now()});save();close();render();toast('Transferencia registrada');
}

function integrationAudit(){
 const issues=[];
 const recipeNames=new Set(allRecipes().map(r=>String(r.name||'').trim().toLowerCase()).filter(Boolean));
 (state.sales||[]).forEach(s=>{if(s.inventoryDeducted&&!recipeNames.has(String(s.product||'').trim().toLowerCase()))issues.push(`Venta ${s.id}: marcada con inventario descontado pero sin receta vinculada`)});
 (state.production||[]).forEach(p=>{if(p.inventoryProduced&&!p.inventoryOutput)issues.push(`Producción ${p.id}: marcada como producto terminado sin movimiento de entrada`);if(p.inventoryConsumed&&!p.inventoryConsumption)issues.push(`Producción ${p.id}: marcada como consumo sin detalle de ingredientes`)});
 (state.purchases||[]).forEach(p=>{if(p.inventoryApplied&&!['RECIBIDA','PARCIAL'].includes(String(p.status||'')))issues.push(`Compra ${p.id}: inventario aplicado con estado ${p.status}`)});
 return {ok:issues.length===0,issues,counts:{sales:(state.sales||[]).length,production:(state.production||[]).length,purchases:(state.purchases||[]).length,movements:(state.movements||[]).length,inventory:(state.inventory||[]).length}};
}

function deepSystemAudit(){
 const issues=[],warnings=[];
 const productMap=new Map((master.products||[]).map(x=>[String(x.id),x]));
 const recipeList=allRecipes(); const recipeMap=new Map(recipeList.map(x=>[String(x.id),x]));
 const duplicateIds=(rows,label)=>{const seen=new Set();rows.forEach(x=>{const id=String(x?.id||'').trim();if(!id)return;if(seen.has(id))issues.push(`${label}: ID duplicado ${id}`);else seen.add(id)})};
 duplicateIds(master.products||[],'Productos maestros'); duplicateIds(recipeList,'Recetas/pre-elaborados'); duplicateIds(master.suppliers||[],'Proveedores maestros');
 const productNames=new Set((master.products||[]).map(x=>String(x.name||'').trim().toLowerCase()).filter(Boolean));
 const recipeNames=new Set(recipeList.map(x=>String(x.name||'').trim().toLowerCase()).filter(Boolean));
 const checks={};
 checks.masterProducts=(master.products||[]).length===381;
 checks.masterSuppliers=(master.suppliers||[]).length===30;
 checks.finalRecipes=(master.recipes||[]).filter(x=>x.type==='final').length===119;
 checks.preps=(master.recipes||[]).filter(x=>x.type==='pre').length===Number(master.meta?.prepCount||49);
 if(!checks.masterProducts)warnings.push(`Maestro SUP contiene ${(master.products||[]).length} productos; esperado 381.`);
 if(!checks.masterSuppliers)warnings.push(`Maestro de proveedores contiene ${(master.suppliers||[]).length}; esperado 30.`);
 if(!checks.finalRecipes)warnings.push(`Maestro contiene ${(master.recipes||[]).filter(x=>x.type==='final').length} recetas finales; esperado 119.`);
 if(!checks.preps)warnings.push(`Maestro contiene ${(master.recipes||[]).filter(x=>x.type==='pre').length} pre-elaborados; esperado ${Number(master.meta?.prepCount||49)}.`);
 recipeList.forEach(r=>{
   (r.items||[]).forEach(i=>{
     if(i.productId && !productMap.has(String(i.productId)) && !i.prepId) issues.push(`Receta ${r.name}: productId inexistente ${i.productId}`);
     if(!i.productId && !i.prepId && !productNames.has(String(i.product||i.ingredient||'').trim().toLowerCase())) warnings.push(`Receta ${r.name}: componente sin vínculo maestro: ${i.product||i.ingredient||'—'}`);
   });
 });
 (state.sales||[]).forEach(s=>{if(s.inventoryDeducted&&!s.inventoryImpact?.length)issues.push(`Venta ${s.id}: inventario marcado como descontado sin impacto registrado`);if(s.product&&!recipeNames.has(String(s.product).trim().toLowerCase())&&s.inventoryDeducted)issues.push(`Venta ${s.id}: producto sin receta maestra vinculada`) });
 (state.production||[]).forEach(p=>{if(p.inventoryProduced&&!p.inventoryOutput)issues.push(`Producción ${p.id}: sin movimiento de salida registrado`);if(p.inventoryConsumed&&!p.inventoryConsumption)issues.push(`Producción ${p.id}: sin detalle de consumo registrado`) });
 (state.purchases||[]).forEach(x=>{if(x.inventoryApplied&&String(x.status).toUpperCase()!=='RECIBIDA')issues.push(`Compra ${x.id}: inventario aplicado con estado ${x.status}`)});
 (state.inventory||[]).forEach(x=>{if(x.productId && !productMap.has(String(x.productId)) && !String(x.productId).startsWith('P-'))warnings.push(`Inventario ${x.product}: productId no está en el maestro`)});
 const invKeys=new Map();(state.inventory||[]).forEach(x=>{const k=`${String(x.productId||x.product||'').toLowerCase()}|${String(x.unit||'').toLowerCase()}`;if(invKeys.has(k))warnings.push(`Inventario duplicado: ${x.product} (${x.unit})`);else invKeys.set(k,x.id)});
 const required=['products','ingredients','suppliers','purchases','inventory','movements','waste','sales','production','recipes','preps','barRecipes','barPreps','dreRecords','budgets','employees','employeeConsumptions','resources','events','checklistTasks','managerLogs','incidents','maintenance','partners','companyDocuments','financialDocuments','permits','refrigerationMoves','documents'];
 required.forEach(k=>{if(!Array.isArray(state[k]))issues.push(`Estructura inválida: ${k} no es arreglo`) });
 const rq=master.meta?.reconciliationQueue||{};
 if(Number(master.meta?.reconciliationAmbiguous||0)) warnings.push(`SUP: ${Number(master.meta.reconciliationAmbiguous)} componentes requieren selección entre productos maestros ambiguos.`);
 if(Number(master.meta?.reconciliationMissing||0)) warnings.push(`SUP: ${Number(master.meta.reconciliationMissing)} componentes no tienen producto maestro equivalente; no se asignó un vínculo inventado.`);
 return {ok:issues.length===0,issues,warnings,checks,reconciliation:{resolvedSafe:Number(master.meta?.reconciliationResolvedSafe||0),ambiguous:Number(master.meta?.reconciliationAmbiguous||0),missing:Number(master.meta?.reconciliationMissing||0),queue:rq},counts:Object.fromEntries(required.map(k=>[k,Array.isArray(state[k])?state[k].length:0]))};
}
