function saveEvent(){const g=id=>document.getElementById(id)?.value||'';const name=g('evName').trim();if(!name)return toast('Indica el nombre del evento');const guests=Math.max(1,Number(g('evGuests')||1));const per=Number(g('evPerPerson')||0),discount=Math.min(100,Math.max(0,Number(g('evDiscount')||0))),tax=Math.max(0,Number(g('evTax')||0));const subtotal=guests*per;const discounted=subtotal*(1-discount/100);const total=discounted*(1+tax/100);const cost=['evFood','evBev','evLabor','evTransport','evMaterials','evPackaging','evOther'].reduce((a,id)=>a+Math.max(0,Number(g(id)||0)),0);const obj={id:'EVT-'+Date.now(),name,title:name,client:g('evClient'),contact:g('evContact'),date:g('evDate')||now().slice(0,10),time:g('evTime'),venue:g('evVenue'),eventType:g('evType'),guests,cost,foodCost:Number(g('evFood')||0),beverageCost:Number(g('evBev')||0),laborCost:Number(g('evLabor')||0),transportCost:Number(g('evTransport')||0),materialsCost:Number(g('evMaterials')||0),packagingCost:Number(g('evPackaging')||0),otherCost:Number(g('evOther')||0),pricePerPerson:per,discount,tax,total,notes:g('evNotes'),status:g('evStatus')||'ESTIMADO',updatedAt:now()};state.events=Array.isArray(state.events)?state.events:[];state.events.push(obj);save();close();render();toast('Cotización de evento guardada')}
