  if(a==='create-label-format'){const prod=state.production.find(x=>String(x.id)===String(id));return formatModal(prod?.id||'')}if(a==='print-label')return printLabel(id);if(a==='label'){const prod=state.production.find(x=>String(x.id)===String(id));return prod?labelModal(prod):toast('Producción no encontrada')};if(a==='pdf')return downloadPDF();if(a==='png')return downloadPNG();if(a==='jpg')return downloadJPG();
  if(a==='recipe-page'){const rt=el?.dataset?.type||'final';state[`_${rt}RecipePage`]=Number(el?.dataset?.page||0);return render()}if(a==='generic-page'){const key=el?.dataset?.key||'records';state[`_genericPage_${key}`]=Number(el?.dataset?.page||0);return render()}if(a==='catalog-page'){state._catalogPage=Number(el?.dataset?.page||0);return renderCatalog()}if(a==='inventory-page'){state._inventoryPage=Number(el?.dataset?.page||0);return render()}
  if(a==='edit-purchase')return purchaseEditModal(id);
  if(a==='save-purchase-edit')return savePurchaseEdit(id);
  if(a==='delete-purchase'){const p=(state.purchases||[]).find(x=>String(x.id)===String(id));if(p)reversePurchaseInventory(p);state.purchases=(state.purchases||[]).filter(x=>String(x.id)!==String(id));save();render();return toast('Compra eliminada y su efecto en inventario revertido')}
  if(a==='document-edit')return documentEditModal(id);if(a==='document-delete')return deleteDocument(id);if(a==='document-download')return downloadDocument(id);
  if(a==='new-dre')return dreModal();if(a==='edit-dre')return dreModal(id);if(a==='del-dre'){state.dreRecords=state.dreRecords.filter(x=>String(x.id)!==String(id));save();render();return toast('Registro eliminado')}
  if(a==='new-budget')return budgetModal();if(a==='edit-budget')return budgetModal(id);if(a==='save-budget'){const arr=state.budgets||[];const r=id?arr.find(x=>String(x.id)===String(id)):null;const obj={id:r?.id||'BUD-'+Date.now(),period:document.getElementById('budPeriod').value,category:document.getElementById('budCat').value.trim(),amount:Number(document.getElementById('budAmt').value||0)};state.budgets=id?arr.map(x=>x.id===id?obj:x):[...arr,obj];save();close();render();return toast('Presupuesto guardado')}
  if(a==='secure-new'||a==='secure-edit'||a==='secure-delete'||a==='secure-export'||a==='secure-print')return secureAccess(a,el?.dataset?.key,id);
  if(a==='generic-add'||a==='generic-edit'||a==='generic-delete'||a==='generic-export'||a==='generic-print')return genericAction?.(a,el?.dataset?.key,id);
