/* ===== LRX COMPATIBILITY ENGINES — transactional production/inventory + unified costing ===== */
(function(){
  const mass={lb:453.59237,oz:28.349523125,g:1,kg:1000};
  const vol={floz:29.5735295625,cup:236.5882365,pt:473.176473,qt:946.352946,l:1000,ml:1,gal:3785.411784};
  const aliases={lbs:'lb',pound:'lb',pounds:'lb',ounces:'oz',ounce:'oz',grams:'g',gram:'g',
    kilos:'kg',kilogram:'kg',kilograms:'kg',liters:'l',litre:'l',litro:'l',litros:'l',milliliters:'ml',
    gallon:'gal',gallons:'gal',units:'unit',units:'unit',each:'unit',ea:'unit'};

  function norm(u){u=String(u||'').trim().toLowerCase().replace(/\s+/g,'');return aliases[u]||u;}
  function convert(q,from,to,density){
    q=Number(q); if(!Number.isFinite(q)) throw Error('Cantidad inválida');
    from=norm(from); to=norm(to);
    if(from===to) return q;
    const fm=mass[from], tm=mass[to];
    if(fm&&tm) return q*fm/tm;
    const fv=vol[from], tv=vol[to];
    if(fv&&tv) return q*fv/tv;
    if(density && fm && tv) return q*fm*Number(density)/tv;
    if(density && fv && tm) return q*fv/(Number(density)*tm);
    throw Error('Conversión no disponible entre '+from+' y '+to);
  }
  function unitCost(product){
    // SUP stores `cost` as the purchase cost PER purchase unit (e.g. $2.39/lb),
    // while `price` is the price of the full pack (e.g. $95.60 for 40 lb).
    // Never divide `cost` by packQty again.
    const packQty=Number(product.packQty??1);
    const purchaseUnit=norm(product.unit||'unit');
    const standard=norm(product.standardUnit||purchaseUnit);
    let costPerPurchaseUnit=Number(product.cost);
    if(!Number.isFinite(costPerPurchaseUnit)||costPerPurchaseUnit<=0){
      const packPrice=Number(product.price||0);
      if(!Number.isFinite(packPrice)||packQty<=0)return 0;
      costPerPurchaseUnit=packPrice/packQty;
    }
    let cost;
    try{cost=convert(1,purchaseUnit,standard,product.density)*costPerPurchaseUnit}catch(e){cost=costPerPurchaseUnit;}
    const y=Number(product.yieldFactor);
    if(Number.isFinite(y)&&y>0&&y<=1) cost=cost/y;
    return cost;
  }
  function lineCost(product,qty,unit){
    const standard=norm(product.standardUnit||product.unit||'unit');
    const q=convert(qty,unit,standard,product.density);
    return q*unitCost(product);
  }
  window.LRXCost={normalizeUnit:norm,convert,unitCost,lineCost};
})();
